using Microsoft.AspNetCore.Builder;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Routing;using Microsoft.EntityFrameworkCore;using Mbb.Archive.Modules.Audit.Infrastructure.Persistence;namespace Mbb.Archive.Modules.Audit.Presentation;public static class AuditEndpoints{public static IEndpointRouteBuilder MapAuditEndpoints(this IEndpointRouteBuilder e){e.MapGet("/api/v1/audit/events",async(string? eventName,Guid? documentId,int? take,AuditDbContext db,CancellationToken ct)=>{var q=db.Entries.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(eventName))q=q.Where(x=>x.EventName==eventName);if(documentId is not null)q=q.Where(x=>x.DocumentId==documentId);var items=await q.OrderByDescending(x=>x.Sequence).Take(Math.Clamp(take??100,1,500)).Select(x=>new{x.Sequence,x.MessageId,x.EventName,x.DocumentId,x.OccurredAt,x.ReceivedAt,x.PreviousHash,x.EntryHash}).ToListAsync(ct);return Results.Ok(items);}).WithTags("Audit").RequireAuthorization("permission:audit.read");return e;}}
